CREATE TABLE IF NOT EXISTS products (id BIGINT PRIMARY KEY, name VARCHAR(100) NOT NULL, price DECIMAL(12,2) NOT NULL, stock INT NOT NULL CHECK(stock >= 0));
CREATE TABLE IF NOT EXISTS orders (id VARCHAR(36) PRIMARY KEY, request_key VARCHAR(100) UNIQUE NOT NULL, product_id BIGINT NOT NULL REFERENCES products(id), quantity INT NOT NULL CHECK(quantity > 0), total DECIMAL(14,2) NOT NULL, created_at TIMESTAMP NOT NULL);
MERGE INTO products KEY(id) VALUES(1,'Keyboard',50000,10),(2,'Mouse',25000,20);
